import sys

def can_place_rooms(n, k, rooms, max_distance):
    count = 0
    last_position = -max_distance - 1

    for i in range(n):
        if rooms[i] == '0':
            if i - last_position > max_distance:
                count += 1
                last_position = i

    return count >= k + 1

def find_min_distance(n, k, rooms):
    low = 1
    high = n // (k + 1)

    while low < high:
        mid = (low + high) // 2
        if can_place_rooms(n, k, rooms, mid):
            high = mid
        else:
            low = mid + 1

    return low

